    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int m = Integer.parseInt(st.nextToken());
        String[] names = new String[m];
        int[] prices = new int[m];
        for (int i = 0; i < m; i++) {
            names[i] = st.nextToken();
            prices[i] = Integer.parseInt(st.nextToken());
        }
        int target = Integer.parseInt(st.nextToken());
        List<List<String>> orders = possibleOrders(names, prices, target);
        StringBuilder sb = new StringBuilder();
        sb.append(orders.size()).append('\n');
        for (List<String> o : orders) sb.append(String.join(" ", o)).append('\n');
        System.out.print(sb);
    }
}
